import json
import re
import sys

import framework_evidence

TARGET = "192.168.5.6"
SERVICES = {
    "Druid": "Apache Druid 0.20.0, directly observed on HTTP port 8081",
    "ZooKeeper": "ZooKeeper 3.4.14, directly observed on TCP port 2181",
}
SEARCH_COMMANDS = [
    "search type:exploit druid",
    "search type:exploit zookeeper",
]
MODULE_RE = re.compile(r"(?<![A-Za-z0-9_./-])exploit/[A-Za-z0-9_./-]+")


def run_console(commands):
    command_string = "; ".join(commands + ["exit"])
    argv = ["msfconsole", "-q", "-x", command_string]
    return {"argv": argv, "envelope": framework_evidence.run_tool(argv)}


def stdout_streams(value):
    """Extract stdout fields without discarding or rewriting the raw envelope."""
    streams = []
    if isinstance(value, dict):
        direct = value.get("stdout")
        if isinstance(direct, str):
            streams.append(direct)
        runs = value.get("tool_runs")
        if isinstance(runs, list):
            for run in runs:
                if isinstance(run, dict) and isinstance(run.get("stdout"), str):
                    streams.append(run["stdout"])
    return streams


def main():
    report = {
        "target": TARGET,
        "observed_services_considered": SERVICES,
        "method": "Metasploit console search and info only; no exploit execution; Searchsploit not used",
        "searches": [],
        "module_info": None,
        "candidate_module_paths": [],
        "coverage_assessment": "",
        "errors": [],
    }

    try:
        search_run = run_console(SEARCH_COMMANDS)
        report["searches"] = [{"commands": SEARCH_COMMANDS, **search_run}]
        streams = stdout_streams(search_run["envelope"])
        if not streams:
            report["errors"].append("Could not extract Metasploit search stdout from the evidence envelope.")
        combined = "\n".join(streams)
        paths = sorted(set(MODULE_RE.findall(combined)))
        report["candidate_module_paths"] = paths

        if paths:
            info_commands = ["info " + path for path in paths]
            info_run = run_console(info_commands)
            report["module_info"] = {"commands": info_commands, **info_run}
            if not stdout_streams(info_run["envelope"]):
                report["errors"].append("Could not extract Metasploit module-info stdout from the evidence envelope.")

        if report["errors"]:
            report["coverage_assessment"] = (
                "Searches were attempted, but evidence extraction was incomplete; results are inconclusive. "
                "Consult the retained raw envelopes and errors."
            )
        else:
            report["coverage_assessment"] = (
                "The reviewed search scope is limited to Metasploit exploit-module searches for the terms "
                "'druid' and 'zookeeper'. Candidate paths extracted from the search output were passed to "
                "Metasploit's info command. Assess raw exit statuses and output to determine whether searches "
                "and inspections completed; this does not establish coverage of differently named or "
                "non-exploit modules."
            )
            if not paths:
                report["coverage_assessment"] += (
                    " No exploit module paths were extracted from the available search stdout; this is a "
                    "negative finding only if both console searches completed successfully."
                )
    except Exception as exc:
        report["errors"].append(type(exc).__name__ + ": " + str(exc))
        report["coverage_assessment"] = "Investigation did not complete; any missing search or inspection result is unknown."

    json.dump(report, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()
